INSERT INTO editions (id, title, publish_date, created_at, status, lead_card, why, judgment_json, posting_notes_json, sources_json, content_json, decided_by, decided_at, decided_via, updated_at) VALUES ('SK-2026-10-05', 'Tabriz, 1294: the paper money the bazaar refused', '2026-10-05', '2026-10-01T10:30:00Z', 'approved', 'REG-0002', 'In 1294 the Mongol ruler of Iran ordered Tabriz to use Chinese-style paper money, and refusing it was punishable by death. The bazaar stopped trading and, about two months later, the paper was withdrawn. Surprising, local to our Iranian and Turkish readers, and a lesson about trust in money.', '[]', '["Farsi Telegram pun «چاو هیچ‌وقت سکه نشد» kept.","Turkish \"kelime-i şehadet\" kept.","English Telegram (about 1,030 characters): post as a text message, image separately.","Carousel slide 3: CC0 Met Museum image of a Yuan-dynasty note, captioned \"The Chinese model\".","Label every AI-made slide or reel shot \"illustration\"."]', '[{"title":"Encyclopaedia Iranica, \"Čāv\" (P. Jackson)","url":"https://www.iranicaonline.org/articles/cav-cao-from-chinese-chao-paper-money-assignat-mathews-chinese-english-dictionary-no/"},{"title":"Encyclopaedia Iranica, \"Economy v\" (A. K. S. Lambton)","url":"https://www.iranicaonline.org/articles/economy-5-part2/"},{"title":"H. H. Howorth, History of the Mongols, Part III (1888), pp. 370–371","url":"https://archive.org/details/historyofmongols03howouoft"},{"title":"Sveriges Riksbank, First banknotes in Europe","url":"https://www.riksbank.se/en-gb/about-the-riksbank/history/historical-timeline/1600-1699/first-banknotes-in-europe/"}]', '{"EN":{"carousel":"| # | Slide text | Visual |\n|---|---|---|\n| 1 | **1294. Tabriz. Refuse this money and the penalty is death.** · From Our Region | Dark engraved-style illustration of a blank paper note over a Tabriz bazaar silhouette; Sikke logo small |\n| 2 | Iran, 1294. Tabriz is ruled by the Mongol Ilkhan Gaykhatu. | Illustrated map: Tabriz marked, Ilkhanate outline |\n| 3 | His vizier borrows an idea from Mongol-ruled China: money made of paper. | Yuan-dynasty chao note, captioned \"The Chinese model\" (licensed museum image) |\n| 4 | 12 September 1294. The notes appear. They are called čāv. | Date set large in engraved numerals |\n| 5 | Chinese characters and the Muslim declaration of faith, on the same note. | Illustration (labelled \"illustration\"), no claim it is a surviving note |\n| 6 | The order: hand in your coins. Refuse the paper, and the penalty is death. | Town crier silhouette, coins pouring into a chest |\n| 7 | Tabriz obeys. For about a week. Then the shops empty. Prices in paper jump more than tenfold. | Empty bazaar arcade, shutters down |\n| 8 | About two months later, the government gives in. The paper is withdrawn. | Torn note drifting |\n| 9 | No order could create trust. Europe''s first banknotes came 360+ years later: Stockholm, 1661. | Timeline bar: 1294 → 1661 |\n| 10 | Save this for the next time someone says \"money is just paper.\" · Sources: Encyclopaedia Iranica · Howorth (1888) · Riksbank | Sikke end card |\n\n### Instagram caption (EN)\n\nIran tried paper money in 1294. The penalty for refusing it was death. The bazaar refused anyway.\n\nGaykhatu, the Mongol ruler in Tabriz, copied the notes of Yuan China. The new čāv carried Chinese characters and the Muslim declaration of faith. Still, prices in paper rose more than tenfold and trade stopped. About two months later, the order was withdrawn.\n\nChina had already used paper money for two centuries. Europe would wait until 1661.\n\nWhat would it take for you to trust a brand-new kind of money?\n\nSources: Encyclopaedia Iranica · Howorth, History of the Mongols (1888)\n\n#Sikke #TEAMedia #MoneyHistory #FinanceFacts #Tabriz #IranHistory #PaperMoney\n\n### Facebook caption (EN)\n\nIn 1294, Tabriz was ordered to use paper money. Refusing it was punishable by death.\n\nThe city still said no, in the only way a city can: shops closed, people left, and the bazaar stopped trading. About two months later, the paper money was gone.\n\nMore than 700 years later, it''s still the best reminder that money runs on trust. Swipe through the story.\n\nSources: Encyclopaedia Iranica · Howorth (1888)\n#Sikke #TEAMedia","linkedin":"In 1294, a government made it punishable by death to refuse its new currency.\n\nThe currency still failed within about two months.\n\nThe place was Tabriz, under the Mongol Ilkhanate. The ruler''s vizier copied the paper money of Yuan China. The notes, called čāv, carried Chinese characters and the Muslim declaration of faith. Coins had to be handed in for exchange.\n\nThe city obeyed for about a week. Then the shops emptied, prices in paper rose more than tenfold, and the bazaar stopped trading. The order was withdrawn.\n\nThree lessons that still hold:\n\n1. Trust can''t be decreed. A mandate can force a launch; only confidence keeps a currency, a product or a platform alive.\n2. Markets vote with their feet. The bazaar didn''t argue. It simply stopped trading.\n3. Rules don''t replace credibility. A death penalty could force people to hold the notes, but not to sell their goods for them.\n\nEurope''s first banknotes appeared more than 360 years later, in Stockholm in 1661.\n\nWhere do you see organisations today asking for trust before they have earned it?\n\nSources: Encyclopaedia Iranica; Howorth, History of the Mongols (1888); Sveriges Riksbank.\n\n#Sikke #TEAMedia #FinancialHistory #Leadership #Trust","reel":"| Time | Voiceover | On-screen text | Shot / visual |\n|---|---|---|---|\n| 0–2 s | \"In 1294, refusing this money was punishable by death.\" | REFUSE IT = DEATH | Paper note slams onto a table |\n| 2–7 s | \"In Tabriz, Iran''s Mongol ruler copied an idea from China: paper money.\" | Tabriz, 1294 | Map zoom to Tabriz |\n| 7–13 s | \"The notes were called čāv. Everyone had to hand in their coins.\" | Hand in your coins | Coins pouring into a chest |\n| 13–20 s | \"Tabriz obeyed for about a week. Then the shops emptied, and prices in paper rose more than tenfold.\" | Prices 10×+ | Empty bazaar, shutters closing |\n| 20–28 s | \"About two months later, the ruler gave in. The paper money was withdrawn.\" | Withdrawn | Note tearing |\n| 28–33 s | \"Lesson: you can order people to use money. You can''t order them to trust it.\" | Money = trust | Bazaar reopening, warm light |\n| 33–35 s | — | Sikke · by TEA Media | End card |","telegram":"**In 1294, a ruler in Tabriz made refusing his new money punishable by death. The money was made of paper.**\n\nGaykhatu, the Mongol ruler of Iran, had a vizier with an idea borrowed from China: print it.\n\nOn 12 September 1294 the new notes, called čāv, went into circulation in Tabriz. They carried Chinese characters and the Muslim declaration of faith on the same paper. Coins had to be handed in for exchange. The penalty for refusing the notes was death.\n\nTabriz obeyed for about a week.\n\nThen the shops emptied. Prices in paper rose more than tenfold. Many people left the city, and the bazaar went quiet.\n\nAbout two months later, the government gave in and withdrew the paper money.\n\nThe bazaar had won. Money works when people trust it, not because a ruler orders it. Europe''s first banknotes came more than 360 years later, in Stockholm in 1661.\n\nWould you have taken the paper?\n\nSources: Encyclopaedia Iranica · Howorth, History of the Mongols (1888)\n\nSikke · money''s strangest true stories\n#Sikke #TEAMedia #MoneyHistory","visual":"- Cover and story slides: AI illustrations in an engraving/etching style, palette ink #17262A, teal #0D5E57, gold #8E6A22, paper #EDF1EE. Label slide 5 \"illustration\": no čāv note survives.\n- Slide 3: licensed photo of a Yuan-dynasty chao note (British Museum or Met open access); caption \"The Chinese model\", never as a Tabriz note.\n- Slide 9: simple timeline graphic, 1294 → 1661.\n- Standards: every AI-made slide and reel shot carries a small \"illustration\" label (engraving style can pass for a period print). Do not AI-render the shahada or Chinese characters; show them typeset correctly or leave the note blank. Slide 3: prefer a CC0 image (Met open access); British Museum images are CC BY-NC-SA, so check commercial use first.\n- Farsi slides: right-to-left layout; keep čāv as چاو; Vazirmatn font.","whatsapp":"*1294, Tabriz: refusing paper money was made punishable by death.*\n\nIran''s Mongol ruler copied China and printed notes called čāv. Coins had to be handed in.\n\nThe city answered by stopping. Shops emptied, prices in paper rose more than tenfold, the bazaar went quiet.\n\nAbout two months later, the paper was withdrawn.\n\nMoney runs on trust, not orders.\n\nSource: Encyclopaedia Iranica\n_Sikke · money''s strangest true stories_"},"FA":{"carousel":"Right-to-left layout; Vazirmatn; visuals as in the EN visual brief.\n\n| # | متن اسلاید |\n|---|---|\n| 1 | **۱۲۹۴ میلادی. تبریز. این پول را رد کنی، مجازاتت مرگ است.** · از منطقهٔ ما |\n| 2 | ایران، سال ۱۲۹۴ میلادی. ایلخان مغول، گیخاتو، بر تبریز فرمان می‌راند. |\n| 3 | وزیرش ایده‌ای را از چینِ زیر سلطهٔ مغول‌ها وام می‌گیرد: پولی از جنس کاغذ. |\n| 4 | ۱۲ سپتامبر ۱۲۹۴ (۱۹ شوال ۶۹۳ ق). اسکناس‌ها از راه می‌رسند. اسمشان «چاو» است. |\n| 5 | خط چینی و شهادتین، روی یک اسکناس. |\n| 6 | فرمان این است: سکه‌هایتان را تحویل بدهید. کاغذ را رد کنید، مجازاتتان مرگ است. |\n| 7 | تبریز اطاعت می‌کند. حدود یک هفته. بعد مغازه‌ها خالی می‌شوند و قیمت‌ها به حساب چاو بیش از ده برابر می‌شود. |\n| 8 | حدود دو ماه بعد، حکومت کوتاه می‌آید. کاغذها جمع می‌شوند. |\n| 9 | هیچ فرمانی اعتماد نساخت. اولین اسکناس‌های اروپا بیش از ۳۶۰ سال بعد آمدند: استکهلم، ۱۶۶۱ میلادی. |\n| 10 | ذخیره‌اش کن برای دفعهٔ بعد که کسی گفت «پول فقط یک تکه کاغذ است.» · منابع: دانشنامهٔ ایرانیکا · هاورث (۱۸۸۸) · ریکسبانک سوئد |\n\nSlide 5 label on the image: «تصویرسازی» (no čāv note survives). Slide 3 caption on the Yuan note: «الگوی چینی».\n\n### Instagram caption (FA)\n\nایران سال ۱۲۹۴ میلادی پول کاغذی را امتحان کرد. مجازات نپذیرفتنش مرگ بود. بازار تبریز باز هم نپذیرفت.\n\nگیخاتو، فرمانروای مغول در تبریز، از روی اسکناس‌های چینِ دورهٔ یوآن الگو گرفت. روی چاو تازه هم خط چینی بود و هم شهادتین. با این حال قیمت‌ها به حساب چاو بیش از ده برابر شد و داد و ستد خوابید. حدود دو ماه بعد، فرمان پس گرفته شد.\n\nچین آن موقع دو قرن بود که پول کاغذی داشت. اروپا باید تا ۱۶۶۱ میلادی صبر می‌کرد.\n\nچه چیزی لازم است تا شما به یک پول کاملاً تازه اعتماد کنید؟\n\nمنابع: دانشنامهٔ ایرانیکا · هاورث، «تاریخ مغول‌ها» (۱۸۸۸)\n\n#سکه #تاریخ_پول #تبریز #تاریخ_ایران #پول_کاغذی #دانستنی_مالی #Sikke #TEAMedia\n\n### Facebook caption (FA)\n\nسال ۱۲۹۴ میلادی، به تبریز دستور دادند با پول کاغذی معامله کند. نپذیرفتنش مجازات مرگ داشت.\n\nشهر باز هم «نه» گفت؛ به تنها زبانی که یک شهر بلد است: مغازه‌ها بسته شد، مردم رفتند و بازار از داد و ستد افتاد. حدود دو ماه بعد، دیگر خبری از پول کاغذی نبود.\n\nبیش از ۷۰۰ سال گذشته و این ماجرا هنوز بهترین یادآوری است که پول با اعتماد زنده است. ورق بزنید و داستان را ببینید.\n\nمنابع: دانشنامهٔ ایرانیکا · هاورث (۱۸۸۸)\n#سکه #TEAMedia","linkedin":"سال ۱۲۹۴ میلادی، حکومتی رد کردن پول تازه‌اش را جرمی با مجازات مرگ اعلام کرد.\n\nاین پول باز هم ظرف حدود دو ماه شکست خورد.\n\nمحل ماجرا تبریز بود، در دوران ایلخانان مغول. وزیرِ فرمانروا از روی پول کاغذی چینِ دورهٔ یوآن الگو گرفت. اسکناس‌ها که «چاو» نام داشتند، هم خط چینی داشتند و هم شهادتین. سکه‌ها باید برای تعویض تحویل داده می‌شد.\n\nشهر حدود یک هفته اطاعت کرد. بعد مغازه‌ها خالی شد، قیمت‌ها به حساب چاو بیش از ده برابر شد و بازار از داد و ستد ایستاد. فرمان پس گرفته شد.\n\nسه درس که هنوز اعتبار دارد:\n\n۱. اعتماد با بخشنامه ساخته نمی‌شود. اجبار می‌تواند یک پول، یک محصول یا یک پلتفرم را راه بیندازد؛ اما فقط اطمینان است که آن را زنده نگه می‌دارد.\n۲. بازار با پاهایش رأی می‌دهد. بازار تبریز بحث نکرد؛ فقط دست از معامله کشید.\n۳. قانون جای اعتبار را نمی‌گیرد. حکم مرگ می‌توانست مردم را به نگه داشتن اسکناس وادار کند، اما نه به فروختن کالایشان در ازای آن.\n\nاولین اسکناس‌های اروپا بیش از ۳۶۰ سال بعد، در سال ۱۶۶۱ میلادی در استکهلم منتشر شد.\n\nامروز کجا می‌بینید سازمان‌ها پیش از به دست آوردن اعتماد، آن را طلب می‌کنند؟\n\nمنابع: دانشنامهٔ ایرانیکا؛ هاورث، «تاریخ مغول‌ها» (۱۸۸۸)؛ ریکسبانک سوئد.\n\n#سکه #TEAMedia #تاریخ_مالی #رهبری #اعتماد\n\nIntended account: same as EN edition (TEA Media page or founders'' personal profiles; Farsi version suits a founder''s profile).","reel":"| زمان | صدای راوی | متن روی تصویر | نما / تصویر |\n|---|---|---|---|\n| ۰–۲ ثانیه | «سال ۱۲۹۴ میلادی، مجازات رد کردن این پول مرگ بود.» | ردش کنی = مرگ | اسکناس کاغذی محکم روی میز کوبیده می‌شود |\n| ۲–۷ ثانیه | «در تبریز، فرمانروای مغول ایران ایده‌ای را از چین برداشت: پول کاغذی.» | تبریز، ۱۲۹۴ میلادی | زوم روی نقشه تا تبریز |\n| ۷–۱۳ ثانیه | «اسم این اسکناس‌ها چاو بود. همه باید سکه‌هایشان را تحویل می‌دادند.» | سکه‌هایت را تحویل بده | ریختن سکه‌ها در صندوق |\n| ۱۳–۲۰ ثانیه | «تبریز حدود یک هفته تن داد. بعد مغازه‌ها خالی شد و قیمت‌ها به حساب چاو بیش از ده برابر شد.» | قیمت‌ها: بیش از ۱۰ برابر | بازار خالی، کرکره‌ها پایین می‌آیند |\n| ۲۰–۲۸ ثانیه | «حدود دو ماه بعد، فرمانروا کوتاه آمد. پول کاغذی پس گرفته شد.» | پس گرفته شد | پاره شدن اسکناس |\n| ۲۸–۳۳ ثانیه | «درسش؟ می‌شود مردم را مجبور کرد با پولی معامله کنند. نمی‌شود مجبورشان کرد به آن اعتماد کنند.» | پول = اعتماد | بازار دوباره باز می‌شود، نور گرم |\n| ۳۳–۳۵ ثانیه | — | سکه · TEA Media | کارت پایانی |\n\nSpoken words: about ۸۵ (Farsi runs slightly longer; each line fits its slot at a calm pace).","telegram":"**سال ۱۲۹۴ میلادی، تبریز: هر کس پول تازهٔ حکومت را قبول نمی‌کرد، مجازاتش مرگ بود. و این پول… از کاغذ بود.**\n\nگیخاتو، فرمانروای مغول ایران، وزیری داشت با ایده‌ای که از چین آورده بود: «پول را چاپ کنیم.»\n\nروز ۱۲ سپتامبر ۱۲۹۴ (۱۹ شوال ۶۹۳ ق) اسکناس‌های تازه با نام «چاو» در تبریز به جریان افتاد. روی یک تکه کاغذ، هم خط چینی بود و هم شهادتین. سکه‌ها باید برای تعویض تحویل داده می‌شد. مجازات نپذیرفتن چاو، مرگ بود.\n\nتبریز حدود یک هفته تن داد.\n\nبعد مغازه‌ها خالی شد. قیمت‌ها به حساب چاو بیش از ده برابر شد. خیلی‌ها شهر را ترک کردند و بازار از نفس افتاد.\n\nحدود دو ماه بعد، حکومت کوتاه آمد و پول کاغذی را جمع کرد.\n\nبازار تبریز برده بود؛ چاو هیچ‌وقت «سکه» نشد. پول با اعتماد کار می‌کند، نه با فرمان. اولین اسکناس‌های اروپا بیش از ۳۶۰ سال بعد، در سال ۱۶۶۱ میلادی در استکهلم منتشر شد.\n\nشما جای تبریزی‌ها بودید، آن کاغذ را قبول می‌کردید؟\n\nمنابع: دانشنامهٔ ایرانیکا · هاورث، «تاریخ مغول‌ها» (۱۸۸۸)\n\nسکه · عجیب‌ترین داستان‌های واقعی پول\n#سکه #تاریخ_پول #تبریز","visual":"- Same visuals as the EN edition; all Farsi slides right-to-left, Vazirmatn font, Persian digits on every slide (slide 9 timeline runs from ۱۲۹۴ on the right to ۱۶۶۱ on the left).\n- Slide 5 image labelled «تصویرسازی»: no čāv note survives.\n- Slide 3: licensed Yuan-dynasty chao photo captioned «الگوی چینی», never presented as a Tabriz note.\n- Name spellings: čāv = چاو · Gaykhatu = گیخاتو · Ilkhanate = ایلخانان · Encyclopaedia Iranica = دانشنامهٔ ایرانیکا · Howorth = هاورث · Riksbank = ریکسبانک سوئد.","whatsapp":"*سال ۱۲۹۴ میلادی، تبریز: نپذیرفتن پول کاغذی، مجازاتش مرگ بود.*\n\nفرمانروای مغول ایران از چین الگو گرفت و اسکناسی به نام «چاو» چاپ کرد. سکه‌ها باید تحویل داده می‌شد.\n\nجواب شهر؟ ایستادن. مغازه‌ها خالی شد، قیمت‌ها به حساب چاو بیش از ده برابر شد و بازار از نفس افتاد.\n\nحدود دو ماه بعد، کاغذها جمع شد.\n\nپول با اعتماد می‌چرخد، نه با دستور.\n\nمنبع: دانشنامهٔ ایرانیکا\n_سکه · عجیب‌ترین داستان‌های واقعی پول_"},"TR":{"carousel":"| # | Slayt metni | Görsel |\n|---|---|---|\n| 1 | **1294. Tebriz. Bu parayı reddedenin cezası ölüm.** · Bölgemizden | EN ile aynı |\n| 2 | 1294, İran. Tebriz''de İlhanlı hükümdarı Geyhatu hüküm sürüyor. | EN ile aynı |\n| 3 | Veziri, Moğol yönetimindeki Çin''den bir fikir ödünç alıyor: kâğıttan para. | EN ile aynı (\"Çin''deki örnek\" başlığıyla) |\n| 4 | 12 Eylül 1294 (19 Şevval 693). Banknotlar ortaya çıkıyor. Adları: çav. | EN ile aynı |\n| 5 | Aynı banknotta hem Çince yazı hem kelime-i şehadet. | EN ile aynı (\"illüstrasyon\" etiketiyle) |\n| 6 | Emir şu: sikkeni teslim et. Kâğıdı reddedenin cezası ölüm. | EN ile aynı |\n| 7 | Tebriz itaat ediyor. Yaklaşık bir hafta. Sonra dükkânlar boşalıyor. Kâğıt para cinsinden fiyatlar on kattan fazla artıyor. | EN ile aynı |\n| 8 | Yaklaşık iki ay sonra yönetim pes ediyor. Kâğıt para kaldırılıyor. | EN ile aynı |\n| 9 | Hiçbir emir güven yaratamadı. Avrupa''nın ilk banknotları 360 yılı aşkın süre sonra geldi: Stockholm, 1661. | EN ile aynı (zaman çizelgesi 1294 → 1661) |\n| 10 | Biri \"para dediğin bir kâğıt parçası\" dediğinde göstermek için kaydet. · Kaynaklar: Encyclopaedia Iranica · Howorth (1888) · Riksbank | Sikke kapanış kartı |\n\n### Instagram caption (TR)\n\nİran 1294''te kâğıt parayı denedi. Reddetmenin cezası ölümdü. Çarşı yine de reddetti.\n\nTebriz''deki İlhanlı hükümdarı Geyhatu, Yuan Çini''nin banknotlarını örnek aldı. Yeni çav''ın üzerinde hem Çince yazı hem kelime-i şehadet vardı. Yine de kâğıt para cinsinden fiyatlar on kattan fazla arttı, ticaret durdu. Yaklaşık iki ay sonra emir geri çekildi.\n\nÇin o sırada kâğıt parayı iki yüzyıldır kullanıyordu. Avrupa ise 1661''i bekleyecekti.\n\nYepyeni bir paraya güvenmeniz için ne gerekirdi?\n\nKaynaklar: Encyclopaedia Iranica · Howorth, History of the Mongols (1888)\n\n#Sikke #TEAMedia #ParaTarihi #FinansBilgisi #Tebriz #İlhanlılar #KâğıtPara\n\n### Facebook caption (TR)\n\n1294''te Tebriz''e kâğıt para kullanma emri verildi. Reddetmenin cezası ölümdü.\n\nŞehir yine de \"hayır\" dedi, hem de bir şehrin diyebileceği tek şekilde: dükkânlar kapandı, insanlar göç etti, çarşıda alışveriş durdu. Yaklaşık iki ay sonra kâğıt para ortadan kalkmıştı.\n\nAradan 700 yılı aşkın zaman geçti; paranın güvenle döndüğünü hâlâ en iyi bu hikâye hatırlatıyor. Hikâyenin tamamı slaytlarda.\n\nKaynaklar: Encyclopaedia Iranica · Howorth (1888)\n#Sikke #TEAMedia #ParaTarihi","linkedin":"1294''te bir yönetim, yeni para birimini reddetmeyi ölümle cezalandırılacak bir suç ilan etti.\n\nPara yine de yaklaşık iki ay içinde çöktü.\n\nYer, İlhanlılar dönemindeki Tebriz. Hükümdarın veziri Yuan Çini''nin kâğıt parasını örnek aldı. \"Çav\" adı verilen banknotlarda Çince yazı ve kelime-i şehadet bulunuyordu. Sikkelerin değiştirilmek üzere teslim edilmesi zorunluydu.\n\nŞehir yaklaşık bir hafta itaat etti. Sonra dükkânlar boşaldı, kâğıt para cinsinden fiyatlar on kattan fazla arttı ve çarşıda ticaret durdu. Emir geri çekildi.\n\nBugün de geçerliliğini koruyan üç ders:\n\n1. Güven emirle kurulmaz. Zorunluluk bir lansmanı başlatabilir; bir parayı, ürünü ya da platformu yaşatan ise güvendir.\n2. Piyasa ayağıyla oy verir. Çarşı tartışmadı; sadece alışverişi kesti.\n3. Kural itibarın yerini tutmaz. Ölüm cezası insanları banknotu elde tutmaya zorlayabilirdi, ama mallarını onunla satmaya değil.\n\nAvrupa''nın ilk banknotları 360 yılı aşkın süre sonra, 1661''de Stockholm''de ortaya çıktı.\n\nSizce bugün hangi kurumlar, güveni hak etmeden önce güven talep ediyor?\n\nKaynaklar: Encyclopaedia Iranica; Howorth, History of the Mongols (1888); Sveriges Riksbank.\n\n#Sikke #TEAMedia #FinansTarihi #Liderlik #Güven","reel":"| Süre | Seslendirme | Ekran yazısı | Çekim / görsel |\n|---|---|---|---|\n| 0–2 sn | \"1294''te bu parayı reddetmenin cezası ölümdü.\" | REDDETMEK = ÖLÜM | Kâğıt banknot masaya çarpıyor |\n| 2–7 sn | \"Tebriz''de İlhanlı hükümdarı Çin''den bir fikir aldı: kâğıt para.\" | Tebriz, 1294 | Haritada Tebriz''e yakınlaşma |\n| 7–13 sn | \"Banknotların adı çavdı. Herkes sikkelerini teslim edecekti.\" | Sikkeleri teslim et | Sikkeler sandığa dökülüyor |\n| 13–20 sn | \"Tebriz yaklaşık bir hafta itaat etti. Sonra dükkânlar boşaldı, kâğıt para cinsinden fiyatlar on kattan fazla arttı.\" | Fiyatlar 10 kattan fazla | Boş çarşı, kepenkler iniyor |\n| 20–28 sn | \"Yaklaşık iki ay sonra hükümdar geri adım attı. Kâğıt para kaldırıldı.\" | Kaldırıldı | Banknot yırtılıyor |\n| 28–33 sn | \"Ders şu: İnsanlara bir parayı kullanmayı emredebilirsiniz. Ona güvenmeyi emredemezsiniz.\" | Para = güven | Çarşı yeniden açılıyor, sıcak ışık |\n| 33–35 sn | — | Sikke · by TEA Media | Kapanış kartı |","telegram":"**1294''te Tebriz''de bir hükümdar, yeni parasını reddetmenin cezasını ölüm olarak belirledi. Para kâğıttandı.**\n\nİlhanlı hükümdarı Geyhatu''nun veziri Çin''den bir fikir getirir: parayı basalım.\n\n12 Eylül 1294''te (Hicri 19 Şevval 693) \"çav\" denen yeni banknotlar Tebriz''de tedavüle girer. Aynı kâğıtta hem Çince yazı hem de kelime-i şehadet vardır. Sikkeler değiştirilmek üzere teslim edilecektir. Kâğıdı reddetmenin cezası ölümdür.\n\nTebriz yaklaşık bir hafta itaat eder.\n\nSonra dükkânlar boşalır. Kâğıt para cinsinden fiyatlar on kattan fazla artar. Birçok kişi şehri terk eder, çarşı susar.\n\nYaklaşık iki ay sonra yönetim geri adım atar ve kâğıt parayı kaldırır.\n\nKazanan çarşı olmuştu. Para, hükümdar emrettiği için değil, insanlar güvendiği için çalışır. Avrupa''nın ilk banknotları ise 360 yılı aşkın süre sonra, 1661''de Stockholm''de çıkacaktı.\n\nSiz olsanız o kâğıdı alır mıydınız?\n\nKaynaklar: Encyclopaedia Iranica · Howorth, History of the Mongols (1888)\n\nSikke · paranın en tuhaf gerçek hikâyeleri\n#Sikke #TEAMedia #ParaTarihi","visual":"- EN görsel brifi aynen geçerli. TR slaytlarında soldan sağa düzen; \"čāv\" yerine \"çav\" yazılır.\n- Slayt 3 başlığı: \"Çin''deki örnek\" (asla Tebriz banknotu olarak gösterilmez).\n- Slayt 5 etiketi: \"illüstrasyon\" (günümüze ulaşmış çav banknotu yok).","whatsapp":"*1294, Tebriz: kâğıt parayı reddetmenin cezası ölümdü.*\n\nİlhanlı hükümdarı Çin''i örnek aldı ve \"çav\" adlı banknotlar bastırdı. Sikkeler teslim edilecekti.\n\nŞehrin cevabı durmak oldu. Dükkânlar boşaldı, kâğıt para cinsinden fiyatlar on kattan fazla arttı, çarşı sustu.\n\nYaklaşık iki ay sonra kâğıt para kaldırıldı.\n\nParayı ayakta tutan emir değil, güvendir.\n\nKaynak: Encyclopaedia Iranica\n_Sikke · paranın en tuhaf gerçek hikâyeleri_"}}', '', '2026-10-01T10:33:00Z', 'chat', '2026-10-01T10:30:00Z');
INSERT INTO edition_notes (id, edition_id, by, kind, text, at) VALUES ('SK-2026-10-05-n1', 'SK-2026-10-05', '', 'claude', 'Test edition 01. Fact-checked (4 corrections to the lead) and cleared by the standards check. Approved by Ardalan in chat on 1 Oct 2026.', '2026-10-01T10:33:00Z');
INSERT INTO editions (id, title, publish_date, created_at, status, lead_card, why, judgment_json, posting_notes_json, sources_json, content_json, decided_by, decided_at, decided_via, updated_at) VALUES ('SK-2026-10-08', 'A trading-bot company allegedly forged its own SEC certificate to convince investors it was real', '2026-10-08', '2026-10-01T15:20:00Z', 'awaiting', 'WIR-0002', 'On 29 Sept 2026 the SEC charged TSAI Pro Ltd. and TSAI Capital Foundation with running an "AI trading bot rental" scheme that allegedly forged its own SEC registration certificate and a government filing to look legitimate. Extremely fresh (2 days old), a classic forged-paperwork con that echoes edition 01''s Alves dos Reis story, and darkly relevant since the scam ran over WhatsApp — one of Sikke''s own platforms.', '["A sibling SEC case from the same day (Cryptoaiml Ltd., draft WIR-0001) wasn''t used as the lead — fine to leave as stock, or say if you''d rather fold it in as a companion post.","Turkey''s $18B investment-fund fraud scandal (131 funds liquidated, 217 suspects) turned up in research and was deliberately NOT written — the fraud facts are clean but it has brushed against Turkish domestic politics (an AKP official''s resignation tied to it). Needs your sign-off per the open regional-politics decision in CLAUDE.md.","Cyprus''s 2013 bail-in and frozen Iranian central-bank reserves abroad also turned up and were deliberately held back — both obvious Money Lock material, both inside the flagged-topics list, awaiting your general decision on regional politics.","A Tehran case (a man murdered for his Bitcoin wallet password) is not ready regardless of the politics question — source conflicts between two Farsi outlets, plus graphic violence and a death sentence under appeal. Needs a third source and standards review before anyone revisits it."]', '["EN Telegram is ~1,047 characters: post as a text message, image separately (over the 1,024-char image-caption limit).","Standards check found the draft WhatsApp and Facebook-caption posts (EN, then same gap found in FA/TR WhatsApp) were missing the alleged/civil-case framing present elsewhere in the pack — all four fixed before delivery; every format now states this is a civil complaint, nothing proven in court, no individual named.","Visual brief: the ''certificate'' prop must read as an editorial illustration only (torn, stamped FORGED, or a generic gold seal) — never a convincing replica of the real SEC seal or a real government document.","No archival/licensed images needed for this story — all visuals are original AI illustrations or data graphics."]', '[{"title":"SEC Charges Multiple Entities in Fraud Schemes Totaling at Least $15 Million That Used WhatsApp, Other Platforms (Press Release 2026-95)","url":"https://www.sec.gov/newsroom/press-releases/2026-95-sec-charges-multiple-entities-fraud-schemes-totaling-least-15-million-used-whatsapp-other-platforms"},{"title":"SEC Litigation Release LR-26654 (SEC v. TSAI Pro Ltd. and TSAI Capital Foundation)","url":"https://www.sec.gov/enforcement-litigation/litigation-releases/lr-26654"}]', '{"EN":{"carousel":"| # | Slide text | Visual |\n|---|---|---|\n| 1 | **They rented out an AI trading bot. It never existed.** · Con of the Week | \"Forged\" certificate illustration, torn/stamped |\n| 2 | 2024. A company invites investors to ''rent'' an AI trading bot. | Chat-bubble UI, \"AI SIGNAL\" glow |\n| 3 | Fees: $100 to $500,000. Bring a friend, earn a commission. | Bar graphic $100→$500,000 |\n| 4 | Investors had one question: is this legal? | Question-mark silhouette |\n| 5 | TSAI Pro had an answer ready: a government certificate. | Certificate illustration, intact, generic gold seal |\n| 6 | Investigators say it was forged. So was a government filing beside it. | Same certificate, cracked/stamped FAKE |\n| 7 | There was no bot. No trades ever happened. | Blank/flatlined trading-screen mockup |\n| 8 | About 1,715 investors. Roughly $2.8 million paid in. | Stacked numbers, gold type |\n| 9 | 29 Sept 2026: the SEC filed a civil fraud case. Nothing proven yet. | Courthouse silhouette / scales icon |\n| 10 | Save this before you ''rent'' anything online. · Source: SEC.gov | Sikke end card, logo, small-text sources |\n\n### Instagram caption (EN)\n\nA company sold investors a trading robot. The robot didn''t exist — and neither did the government approval they showed to prove it was safe.\n\nStarting in 2024, TSAI Pro invited investors to \"rent\" an AI trading bot for $100 to $500,000, promoted over WhatsApp and Facebook, with a commission for every new investor brought in. When people asked if it was legal, the company allegedly produced proof: a certificate claiming registration with the US Securities and Exchange Commission.\n\nThe SEC says it was forged — along with a government filing posted beside it. There was no bot. No trades ever happened. On 29 September 2026, the SEC filed a civil fraud case: about 1,715 investors, roughly $2.8 million paid in.\n\nNothing has been proven in court yet. What would it take for a \"certificate\" to convince you?\n\nSource: SEC.gov\n\n#Sikke #TEAMedia #MoneyHistory #FinanceFacts #ConOfTheWeek #SEC #CryptoFraud\n\n### Facebook caption (EN)\n\nA company sold investors an AI trading bot. The bot never existed — and neither did the government approval they showed to prove it was safe.\n\nTSAI Pro invited investors to \"rent\" the bot for $100 to $500,000, recruiting through WhatsApp and Facebook. When people asked if it was legal, the company allegedly showed them a forged SEC certificate and a fake government filing.\n\nNo bot. No trades. On 29 September 2026, the SEC filed a civil fraud case: about 1,715 investors had paid in roughly $2.8 million. Nothing has been proven in court, and no individual has been named.\n\nThe lesson is an old one, in new clothes: official-looking paperwork still works.\n\nSource: SEC.gov\n#Sikke #TEAMedia","linkedin":"A company convinced investors its AI trading bot was legitimate by forging the one thing that was supposed to prove it: the regulator''s own approval.\n\nStarting in September 2024, TSAI Pro Ltd. invited investors to \"rent\" an AI trading bot, with fees from $100 to $500,000. It recruited through a website, WhatsApp and Facebook, paying commissions to anyone who brought in a new investor.\n\nWhen prospective investors asked whether the company was legitimate, it had an answer: a certificate showing registration with the US Securities and Exchange Commission, and a matching government filing.\n\nThe SEC says both were fabricated. There was no bot. No trades were ever placed with investor money.\n\nOn 29 September 2026, the SEC filed a civil fraud complaint. About 1,715 investors had paid in roughly $2.8 million. The case is civil, not criminal — nothing is proven in court, and no individual has been named.\n\nWhat it teaches us:\nForging the appearance of approval is older than finance itself — only the paperwork changes.\nA recruitment commission is a pyramid in disguise, whatever the product.\n\"Where did this come from?\" is worth asking before \"how much can it make me?\"\n\nWhere else do you see organisations asking for trust before they''ve earned it?\n\nSource: SEC.gov, Press Release 2026-95\n#Sikke #TEAMedia #FinancialHistory #DueDiligence #Fraud","reel":"| Time | Voiceover | On-screen text | Shot / visual |\n|---|---|---|---|\n| 0–5s | \"This certificate looked official — or so it seemed.\" | SEC APPROVED | Certificate graphic close-up; red \"FAKE\" stamp hits |\n| 5–11s | \"They said: rent our AI trading bot.\" | AI SIGNAL | Phone screen, chat-bubble animation |\n| 11–17s | \"Fees: $100 to $500,000.\" | $100 – $500,000 | Fee numbers grow on screen |\n| 17–23s | \"But the certificate was forged. The bot never existed.\" | (certificate cracks) | Certificate graphic cracks and breaks apart |\n| 23–29s | \"1,715 investors. $2.8 million.\" | 1,715 investors · $2.8M | Numbers drop onto screen in sequence |\n| 29–33s | — | Sikke · money''s strangest true stories | Sikke end card |","telegram":"**They \"rented\" out an AI trading bot. The bot never existed — and neither did the government approval they showed to prove it.**\n\nStarting in September 2024, TSAI Pro invited investors to rent an \"AI trading bot\" for $100 to $500,000, promoted over WhatsApp and Facebook. Bring in a friend, and you earned a commission.\n\nWhen investors asked if it was legal, TSAI Pro allegedly had an answer: a certificate claiming registration with the US Securities and Exchange Commission. Investigators say it was forged — along with a government filing posted beside it.\n\nThere was no bot. No trades ever happened. On 29 September 2026, the SEC filed a civil fraud case: about 1,715 investors had paid in roughly $2.8 million.\n\nNothing has been proven in court, and no individual has been charged. But the method is centuries old: forge the official stamp, and people stop asking questions.\n\nWould a \"certificate\" have been enough to convince you?\n\nSource: SEC.gov, Press Release 2026-95\nSikke · money''s strangest true stories\n#Sikke #TEAMedia #CryptoFraud","visual":"Every image is an original AI illustration or data graphic (live 2026 news, no archival image applies). The \"certificate\" prop must read as an editorial illustration only — torn, stamped \"FORGED\" in red, or a generic gold-seal graphic — never a convincing replica of the real SEC seal or a real government document. No real company logos. Palette: ink #17262A, teal #0D5E57, gold #8E6A22, paper #EDF1EE.","whatsapp":"*A company allegedly sold a trading robot that never existed — and faked the SEC''s approval of it too.*\nTSAI Pro offered investors an \"AI trading bot\" to rent, for $100 to $500,000 a seat. When asked if it was legal, the SEC says they showed a forged government certificate.\nThere was no bot, the SEC alleges. About 1,715 people paid in roughly $2.8 million before the SEC filed a civil fraud case — a civil complaint, not a criminal charge; nothing is proven in court.\nSource: SEC.gov"},"FA":{"carousel":"۱) جلد: «آن‌ها ربات معامله‌گر هوش مصنوعی اجاره می‌دادند. رباتی وجود نداشت.» · کلاهبرداری این هفته\n۲) «سال ۲۰۲۴ میلادی. شرکتی از سرمایه‌گذاران دعوت می‌کند یک ربات معامله‌گر هوش مصنوعی را «اجاره» کنند.»\n۳) «هزینه: از ۱۰۰ تا ۵۰۰٬۰۰۰ دلار. دوستی را معرفی کن، کمیسیون بگیر.»\n۴) «سرمایه‌گذاران یک سؤال داشتند: این کار قانونی است؟»\n۵) «جواب آماده‌ی TSAI Pro: یک گواهی دولتی.»\n۶) «بازرسان می‌گویند این گواهی جعلی بود. یک سند دولتی دیگر کنارش هم همین‌طور.»\n۷) «هیچ رباتی وجود نداشت. هیچ معامله‌ای هم هرگز انجام نشد.»\n۸) «حدود ۱٬۷۱۵ سرمایه‌گذار. نزدیک به ۲٫۸ میلیون دلار پرداخت‌شده.»\n۹) «۲۹ سپتامبر ۲۰۲۶ میلادی (۷ مهر ۱۴۰۵): SEC شکایتی مدنی ثبت کرد. هنوز چیزی اثبات نشده.»\n۱۰) «این را ذخیره کن، پیش از آنکه چیزی را آنلاین «اجاره» کنی.» · منبع: SEC.gov\n\n### کپشن اینستاگرام\n\nشرکتی به سرمایه‌گذاران یک ربات معامله‌گر فروخت. رباتی وجود نداشت — و تأییدیه‌ی دولتی که برای اثبات امن‌بودنش نشان می‌دادند هم وجود نداشت.\n\nاز سپتامبر ۲۰۲۴ میلادی (۱۴۰۳)، TSAI Pro به سرمایه‌گذاران پیشنهاد می‌داد «ربات معامله‌گر هوش مصنوعی»‌اش را با ۱۰۰ تا ۵۰۰٬۰۰۰ دلار اجاره کنند؛ تبلیغات در واتس‌اپ و فیسبوک، با کمیسیون برای هرکس دوستی معرفی می‌کرد.\n\nوقتی سؤال قانونی‌بودن مطرح می‌شد، ظاهراً گواهی‌ای جعلی از SEC نشان می‌دادند. هیچ رباتی نبود، هیچ معامله‌ای هم انجام نشد. SEC در ۲۹ سپتامبر ۲۰۲۶ میلادی (۷ مهر ۱۴۰۵) شکایت کرد: حدود ۱٬۷۱۵ سرمایه‌گذار، نزدیک به ۲٫۸ میلیون دلار پرداخته بودند. هیچ‌کس هنوز محکوم نشده.\n\nچه چیزی لازم بود تا یک «گواهی» شما را متقاعد کند؟\n\nمنبع: SEC.gov\n#Sikke #TEAMedia #تاریخ_پول #کلاهبرداری_هفته #SEC #ارز_دیجیتال #هوش_مصنوعی\n\n### کپشن فیسبوک\n\nیک شرکت به آدم‌ها گفت: «ربات معامله‌گر هوش مصنوعی ما را اجاره کن، پول دربیار.» مشکل این‌جا بود که نه ربات واقعی بود، نه آن گواهی رسمی‌ای که برای اثباتش نشان می‌دادند.\n\nشرکت TSAI Pro از سپتامبر ۲۰۲۴ میلادی (۱۴۰۳)، در واتس‌اپ و فیسبوک، پیشنهاد اجاره‌ی ربات را با ۱۰۰ تا ۵۰۰٬۰۰۰ دلار مطرح می‌کرد. وقتی کسی می‌پرسید قانونی است؟، ظاهراً گواهی‌ای از SEC نشان می‌دادند که بعداً بازرسان گفتند جعلی بوده.\n\nنتیجه؟ هیچ رباتی، هیچ معامله‌ای. SEC در ۲۹ سپتامبر ۲۰۲۶ میلادی (۷ مهر ۱۴۰۵) شکایت کرد: نزدیک به ۱٬۷۱۵ نفر، روی‌هم حدود ۲٫۸ میلیون دلار پرداخته بودند. هنوز چیزی در دادگاه ثابت نشده.\n\nشما را یک «مُهر رسمی» متقاعد می‌کند؟\n\nمنبع: SEC.gov\n#Sikke #TEAMedia #کلاهبرداری","linkedin":"یک شرکت سرمایه‌گذاران را متقاعد کرد که ربات معامله‌گر هوش مصنوعی‌اش قانونی است — با جعل همان چیزی که قرار بود این موضوع را ثابت کند: تأییدیه‌ی خودِ نهاد ناظر.\n\nاز سپتامبر ۲۰۲۴ میلادی (۱۴۰۳)، TSAI Pro Ltd. و TSAI Capital Foundation از طریق وب‌سایت، واتس‌اپ و فیسبوک به سرمایه‌گذاران پیشنهاد می‌دادند یک «ربات معامله‌گر هوش مصنوعی» را با مبلغی بین ۱۰۰ تا ۵۰۰٬۰۰۰ دلار اجاره کنند، همراه با ساختار کمیسیونِ معرفی سرمایه‌گذار جدید.\n\nبه گفته‌ی کمیسیون بورس و اوراق بهادار آمریکا (SEC)، این شرکت یک گواهی جعلی از خودِ SEC و یک سند ثبتی ساختگی منتشر کرده بود تا ثبت‌شده و رسمی به‌نظر برسد. هیچ رباتی وجود نداشت، هیچ معامله‌ی واقعی‌ای هم انجام نشد.\n\nSEC در ۲۹ سپتامبر ۲۰۲۶ میلادی (۷ مهر ۱۴۰۵) شکایتی مدنی ثبت کرد: حدود ۱٬۷۱۵ سرمایه‌گذار روی‌هم نزدیک به ۲٫۸ میلیون دلار پرداخته بودند. این یک شکایت مدنی است، نه اتهام کیفری — هنوز چیزی در دادگاه اثبات نشده و هیچ فردی نامبرده یا محکوم نشده.\n\nچه درسی می‌گیریم؟\nجعلِ ظاهرِ تأییدِ رسمی، قدیمی‌تر از خودِ صنعت مالی است.\nساختار کمیسیونِ معرفی، معمولاً یک طرح هرمی با لباس دیگر است.\nپیش از پرسیدن «چقدر سود می‌دهد؟»، بپرس «این مجوز از کجا آمده؟»\n\nکجاهای دیگر می‌بینید که یک سازمان پیش از آنکه اعتماد را به‌دست بیاورد، از شما می‌خواهد به او اعتماد کنید؟\n\nمنبع: SEC.gov\n#Sikke #TEAMedia #تاریخ_مالی #بررسی_دقیق #کلاهبرداری","reel":"| زمان | روایت صوتی | متن روی تصویر | تصویر/نما |\n|---|---|---|---|\n| ۰–۳ ثانیه | «این گواهی SEC واقعی به‌نظر می‌رسید.» | گواهی‌ای که جعلی بود | مهر قرمز «جعلی» روی گواهی کوبیده می‌شود |\n| ۳–۸ ثانیه | «یک شرکت می‌گفت: ربات معامله‌گر هوش مصنوعی ما را اجاره کن.» | «سیگنال هوش مصنوعی» | حباب چت با متن «سیگنال AI» |\n| ۸–۱۴ ثانیه | «هزینه؟ از ۱۰۰ تا ۵۰۰هزار دلار.» | ۱۰۰ دلار ← ۵۰۰٬۰۰۰ دلار | اعداد هزینه روی صفحه بزرگ می‌شوند |\n| ۱۴–۲۰ ثانیه | «اما این مجوز، جعلی بود.» | گواهی ترک می‌خورَد | ترک‌خوردن و شکستن گرافیک گواهی |\n| ۲۰–۲۸ ثانیه | «حدود ۱٬۷۱۵ سرمایه‌گذار، ۲٫۸ میلیون دلار از دست دادند.» | ۱٬۷۱۵ سرمایه‌گذار · ۲٫۸M$ | آمار روی پس‌زمینه‌ی تیره ظاهر می‌شود |\n| ۲۸–۳۳ ثانیه | «سکه، عجیب‌ترین داستان‌های واقعی پول.» | سکه | کارت پایانی با لوگوی سکه |","telegram":"**یک شرکت ادعا می‌کرد می‌توانید ربات معامله‌گر هوش مصنوعی‌اش را «اجاره» کنید. نه ربات واقعی بود، نه مجوزی که برای اثباتش نشان می‌دادند.**\n\nاز سپتامبر ۲۰۲۴ میلادی (۱۴۰۳)، شرکتی به نام TSAI Pro به سرمایه‌گذاران پیشنهاد می‌داد یک «ربات معامله‌گر مبتنی‌بر هوش مصنوعی» را با مبلغی بین ۱۰۰ تا ۵۰۰٬۰۰۰ دلار اجاره کنند؛ تبلیغاتش در واتس‌اپ و فیسبوک پخش می‌شد. دوستی را هم معرفی می‌کردید، کمیسیون می‌گرفتید.\n\nوقتی سرمایه‌گذاران می‌پرسیدند «این کار قانونی است؟»، TSAI Pro ظاهراً جوابی آماده داشت: گواهی‌ای که مدعی بود این شرکت نزد کمیسیون بورس و اوراق بهادار آمریکا (SEC) به‌ثبت رسیده. بازرسان می‌گویند این گواهی جعلی بوده.\n\nهیچ رباتی وجود نداشت. هیچ معامله‌ای هم هرگز انجام نشد. در ۲۹ سپتامبر ۲۰۲۶ میلادی (۷ مهر ۱۴۰۵)، SEC شکایتی مدنی با عنوان کلاهبرداری ثبت کرد: حدود ۱٬۷۱۵ سرمایه‌گذار، روی‌هم نزدیک به ۲٫۸ میلیون دلار پرداخته بودند.\n\nهنوز هیچ‌چیز در دادگاه اثبات نشده و هیچ فردی به‌طور شخصی متهم نشده.\n\nیک «گواهی» برای متقاعدکردن شما کافی بود؟\n\nمنبع: SEC.gov، بیانیه مطبوعاتی شماره ۲۰۲۶-۹۵\nسکه · عجیب‌ترین داستان‌های واقعی پول\n#Sikke #TEAMedia #کلاهبرداری_دیجیتال","visual":"مانند نسخه‌ی انگلیسی — همه‌ی تصاویر، تصویرسازی هوش‌مصنوعی یا نمودار داده‌ هستند. گواهی جعلی باید آشکارا به‌صورت تصویرسازی ویرایشی دیده شود — هرگز شبیه مُهر واقعی SEC یا سند دولتی واقعی نباشد.","whatsapp":"*آن‌ها ربات معامله‌گری «اجاره» دادند که اصلاً وجود نداشت — SEC می‌گوید تأییدیه‌اش را هم جعل کرده بودند.*\nشرکت TSAI Pro به سرمایه‌گذاران پیشنهاد می‌داد یک «ربات معامله‌گر هوش مصنوعی» را با مبلغی بین ۱۰۰ تا ۵۰۰٬۰۰۰ دلار اجاره کنند. وقتی می‌پرسیدند قانونی است؟، به گفته‌ی SEC گواهی جعلی از یک نهاد دولتی نشان می‌دادند.\nبه ادعای SEC، هیچ رباتی در کار نبود؛ نزدیک به ۱٬۷۱۵ نفر روی‌هم حدود ۲٫۸ میلیون دلار پرداخته بودند. این یک شکایت مدنی است، نه کیفری — هنوز چیزی در دادگاه اثبات نشده.\nمنبع: SEC.gov"},"TR":{"carousel":"1. Kapak: \"Yapay zekâlı bir trading botu ''kiraladılar''. Hiç var olmadı.\" · Haftanın Dolandırıcılığı\n2. \"2024. Bir şirket yatırımcıları bir yapay zekâ trading botu ''kiralamaya'' davet ediyor.\"\n3. \"Ücretler: 100 dolardan 500.000 dolara kadar. Bir arkadaşını getir, komisyon kazan.\"\n4. \"Yatırımcıların tek bir sorusu vardı: bu yasal mı?\"\n5. \"TSAI Pro''nun hazır bir cevabı vardı: resmi bir devlet sertifikası.\"\n6. \"Soruşturmacılara göre sertifika sahteydi. Yanındaki resmi belge de öyle.\"\n7. \"Ortada bot yoktu. Hiçbir işlem gerçekleşmedi.\"\n8. \"Yaklaşık 1.715 yatırımcı. Toplam 2,8 milyon dolar civarında ödeme.\"\n9. \"29 Eylül 2026: SEC hukuki bir dolandırıcılık davası açtı. Henüz hiçbir şey kanıtlanmadı.\"\n10. \"Bir şeyi ''kiralamadan'' önce bunu kaydet.\" · Source: SEC.gov\n\n### Instagram açıklaması\n\nBir şirket yatırımcılara bir trading robotu sattı. Sorun şu: robot yoktu — güvenli olduğunu kanıtlamak için gösterdikleri devlet onayı da yoktu.\n\n2024''ün Eylül ayından itibaren TSAI Pro, yatırımcıları WhatsApp ve Facebook üzerinden 100 dolardan 500.000 dolara kadar ücretlerle bir \"yapay zekâ trading botu\" kiralamaya çağırdı. Arkadaş getirene komisyon veriliyordu.\n\nYasallığı sorulduğunda TSAI Pro''nun elinde bir sertifika vardı: SEC''e kayıtlı olduklarını gösteren bir belge. Soruşturmacılara göre bu belge sahteydi — yanındaki resmi başvuru kaydı da öyle.\n\nBot hiç var olmadı. Hiçbir işlem yapılmadı. 29 Eylül 2026''da SEC dava açtı: yaklaşık 1.715 yatırımcıdan toplam 2,8 milyon dolar civarında para toplanmıştı.\n\nBir \"sertifika\" sizi ikna etmeye yeter miydi?\n\n#Sikke #TEAMedia #ParaTarihi #FinansGerçekleri #HaftanınDolandırıcılığı #SEC #KriptoDolandırıcılığı\n\n### Facebook açıklaması\n\nBir şirket düşünün: yatırımcılara \"yapay zekâ ile işlem yapan bir bot\" kiralıyor, üstüne bir de devletin onayladığını söylüyor. Tek sorun: ne bot gerçekti, ne de o onay.\n\n2024 Eylül''den itibaren TSAI Pro, 100 dolardan 500.000 dolara kadar ücretlerle bu \"botu\" WhatsApp ve Facebook''ta pazarladı. Arkadaşını getirene komisyon veriliyordu. Yasal mı diye soranlara SEC''e kayıtlı olduklarını gösteren bir sertifika gösteriyorlardı — soruşturmacılara göre sahte, yanındaki resmi belge de öyle.\n\nGerçekte ne bot vardı, ne de tek bir işlem. 29 Eylül 2026''da SEC dava açtı: yaklaşık 1.715 yatırımcı, toplam 2,8 milyon dolar civarında para yatırmıştı. Mahkemede henüz hiçbir şey kanıtlanmadı.\n\nSource: SEC.gov\n#Sikke #TEAMedia #KriptoDolandırıcılığı","linkedin":"Bir şirket, yapay zekâ destekli trading botunun gerçek olduğuna yatırımcıları ikna etmek için tam da onu kanıtlaması gereken şeyi sahteledi: düzenleyici kurumun kendi onayını.\n\nEylül 2024''ten itibaren TSAI Pro, yatırımcıları 100 dolardan 500.000 dolara kadar değişen ücretlerle bir \"yapay zekâ trading botu\" kiralamaya davet etti. Pazarlama WhatsApp ve Facebook üzerinden yürütülüyordu; bir arkadaşını getirene komisyon veriliyordu.\n\nYasallığı sorulduğunda TSAI Pro''nun bir cevabı vardı: ABD Menkul Kıymetler ve Borsa Komisyonu''na (SEC) kayıtlı olduklarını gösteren bir sertifika.\n\nSoruşturmacılara göre bu sertifika sahteydi — yanına eklenen resmi bir başvuru belgesi de öyle.\n\nOrtada ne bir bot vardı, ne de gerçekleşen bir işlem. 29 Eylül 2026''da SEC hukuki bir dolandırıcılık davası açtı: yaklaşık 1.715 yatırımcıdan toplam 2,8 milyon dolar civarında para toplanmıştı.\n\nBunlar hukuk davasındaki iddialar; mahkemede henüz hiçbir şey kanıtlanmadı ve hiçbir kişi suçlanmadı.\n\nBundan çıkaracağımız ders:\n- Onay görüntüsünü sahtelemek, finans dünyasından bile eski bir yöntem.\n- Arkadaş getirene komisyon veren bir yapı, genellikle piramit şemasının kılık değiştirmiş hâlidir.\n- Parayı yatırmadan önce \"ne kadar kazandırır\" değil, \"bu nereden geliyor\" diye sorun.\n\nKurumlardan güven kazanmadan önce güven talep ettiklerini başka nerelerde görüyorsunuz?\n\nSource: SEC.gov\n#Sikke #TEAMedia #FinansTarihi #DueDiligence #Dolandırıcılık","reel":"| Zaman | Seslendirme | Ekran yazısı | Çekim/görsel |\n|---|---|---|---|\n| 0–5s | \"Bu sertifika resmiydi — ya da öyle görünüyordu.\" | \"SEC ONAYLI\" | Sahte sertifika grafiği yakın çekim; üzerine kırmızı \"SAHTE\" damgası vuruluyor |\n| 5–11s | \"''Yapay zekâ botu'' kiralayın dediler.\" | \"AI SİNYALİ\" | Telefon ekranında sohbet balonu animasyonu |\n| 11–17s | \"Ücret: 100 dolardan 500.000 dolara kadar.\" | \"$100 – $500.000\" | Ücret rakamları ekranda büyüyerek beliriyor |\n| 17–23s | \"Ama sertifika sahteydi. Bot hiç var olmadı.\" | (sertifika çatlıyor) | Sertifika grafiği ortadan çatlayıp parçalanıyor |\n| 23–29s | \"1.715 yatırımcı. 2,8 milyon dolar.\" | \"1.715 kişi · $2,8M\" | Sayılar art arda ekrana düşüyor |\n| 29–33s | \"Sikke · paranın en tuhaf gerçek hikâyeleri\" | logo | Sikke kapanış kartı |","telegram":"**Yapay zekâlı bir \"trading bot\" kiraladılar. Bot hiç var olmadı — üstelik gösterdikleri SEC onayı da sahteymiş.**\n\nEylül 2024''ten itibaren TSAI Pro, yatırımcıları 100 dolardan 500.000 dolara kadar değişen ücretlerle bir \"yapay zekâ trading botu\" kiralamaya davet etti. Reklamlar WhatsApp ve Facebook üzerinden yapılıyordu. Bir arkadaşını getirene komisyon veriliyordu.\n\nYatırımcılar \"bu yasal mı?\" diye sorduğunda TSAI Pro''nun hazır bir cevabı vardı: ABD Menkul Kıymetler ve Borsa Komisyonu''na (SEC) kayıtlı olduklarını gösteren bir sertifika. Soruşturmacılara göre bu sertifika sahteydi.\n\nOrtada bot yoktu. Hiçbir işlem yapılmadı. 29 Eylül 2026''da SEC, hukuki bir dolandırıcılık davası açtı: yaklaşık 1.715 yatırımcı toplam 2,8 milyon dolar civarında para yatırmıştı.\n\nMahkemede henüz hiçbir şey kanıtlanmadı, hiçbir kişi suçlanmadı.\n\nBir \"sertifika\" sizi ikna etmeye yeter miydi?\n\nSource: SEC.gov, Basın Bülteni 2026-95\nSikke · paranın en tuhaf gerçek hikâyeleri\n#Sikke #TEAMedia #KriptoDolandırıcılığı","visual":"EN ile aynı — tüm görseller yapay zekâ illüstrasyonu veya veri grafiğidir. Sahte sertifika editoryal illüstrasyon gibi görünmeli — gerçek SEC mührünün veya gerçek bir devlet belgesinin ikna edici bir kopyası gibi asla görünmemeli.","whatsapp":"*Var olmayan bir trading botunu \"kiraladılar\" — SEC''e göre onayını da sahtelediler.*\nTSAI Pro, yatırımcılara 100 dolardan 500.000 dolara kadar ücretlerle bir \"yapay zekâ trading botu\" kiralama teklif etti. \"Yasal mı?\" diye sorulduğunda, SEC''e göre sahte bir devlet sertifikası gösterdiler.\nSEC''in iddiasına göre ortada bot yoktu; yaklaşık 1.715 kişi toplam 2,8 milyon dolar civarında ödedi. Bu hukuki bir dava, ceza davası değil — henüz mahkemede hiçbir şey kanıtlanmadı.\nSource: SEC.gov"}}', '', '', '', '2026-10-01T15:20:00Z');
INSERT INTO edition_notes (id, edition_id, by, kind, text, at) VALUES ('SK-2026-10-08-claude-2026-10-01', 'SK-2026-10-08', '', 'claude', 'Research: Wire, Crypto & Fintech and Money Lock desks dispatched in parallel (Money Lock''s first-ever run). Lead picked from 22 candidate cards. Independent fact-check (no reporter notes) verified the lead (WIR-0002) and 2 alternates (CRY-0002 Bitget hack, LCK-0002 1933 gold confiscation) with no corrections to WIR-0002''s facts. Standards check found 2 blocking legal-status gaps in the EN pack (WhatsApp and Facebook caption lacked the ''civil complaint, nothing proven, no individual named'' framing present elsewhere) and fixed both; the same gap was then found and fixed in the FA and TR WhatsApp posts. No other blocking issues. Advisory only: keep reel captions carrying the civil-case line when finalized, and keep the illustrated ''certificate'' prop generic (no SEC-specific iconography). A stock check of 6 leftover drafts from edition 01 was also completed this cycle and filed separately (CON-0002, CON-0003, REG-0006, ODD-0003 verified; REG-0005 downgraded to Needs-2nd-source over a disputed date; ODD-0007 verified as a myth-buster). Held back from this edition, pending your decision on the open regional-politics question in CLAUDE.md: Turkey''s $18B fund-fraud scandal (political angle only), Cyprus''s 2013 bail-in, and frozen Iranian central-bank reserves. Also held back regardless of that question: a Tehran Bitcoin-murder case with unresolved source conflicts and graphic content.', '2026-10-01T15:25:00Z');
INSERT INTO cards (id, headline, status, category, era, date, region, country, tags_json, wow, relevance, summary, sources_json, used_in_json, checked_on) VALUES ('CON-0001', 'A con man got Portugal''s own banknote printer to print 580,000 notes for him, and duplicate serial numbers gave it away', 'Verified', 'cons-fraud', 'industrial', '1924–1925', 'europe', 'Portugal', '["Alves dos Reis","Waterlow & Sons","Banco de Portugal","Banco Angola e Metrópole","500 escudo note","Vasco da Gama note","fraud"]', 5, 4, 'In 1924–25 Artur Alves dos Reis used forged contracts, presented as a secret Bank of Portugal loan deal for the colony of Angola, to get Waterlow & Sons, the London firm that printed Portugal''s banknotes, to print 580,000 notes of 500 escudos. Waterlow used the Bank''s own plates (or plates from the same die), so the notes matched genuine ones. In December 1925, after a tip-off, police searched Reis''s Banco Angola e Metrópole in Porto, and Bank of Portugal officials found serial numbers that appeared twice. Reis was sentenced to 20 years in 1930. In 1932 the House of Lords ordered Waterlow to pay the Bank £610,392.', '[{"title":"Banco de Portugal v Waterlow & Sons Ltd [1932] AC 452; [1932] UKHL 1 (28 April 1932), full judgment text","url":"https://lawcarenigeria.com/waterlow-sons-ltd-v-banco-de-portugal-1932-ukhl-1-28-april-1932/"},{"title":"Henry Wigan, The Effects of the 1925 Portuguese Bank Note Crisis, LSE Economic History Working Paper 82/04 (2004)","url":"https://www.lse.ac.uk/Economic-History/Assets/Documents/WorkingPapers/Economic-History/2004/WP8204.pdf"},{"title":"Assembleia da República, Caso Angola e Metrópole – Burla Alves dos Reis (1925)","url":"https://www.parlamento.pt/Parlamento/Paginas/Burla-Alves-dos-Reis.aspx"},{"title":"Banco de Portugal archive, fonds ''Artur Virgílio Alves Reis (Lisboa, 1896-09-08 – Lisboa, 1955-07-09)'' (page title seen in search; page itself returned 403)","url":"https://www.bportugal.pt/arquivo/details?id=48694"},{"title":"Stranger than Fiction: The Portuguese Bank Note Crisis of 1925 (PMG)","url":"https://www.pmgnotes.com/news/article/7138/The-Portuguese-Bank-Note-Crisis-of-1925/"}]', '[]', '2026-10-01');
INSERT INTO cards (id, headline, status, category, era, date, region, country, tags_json, wow, relevance, summary, sources_json, used_in_json, checked_on) VALUES ('CON-0002', 'The great salad oil swindle — tanks of "soybean oil" that were mostly seawater nearly sank American Express', 'Verified', 'cons-fraud', 'post-war', '1963', 'americas', 'United States', '["Tino De Angelis","Allied Crude Vegetable Oil","American Express","warehouse receipts","collateral fraud","Bayonne","Ira Haupt"]', 5, 3, 'Tino De Angelis''s Allied Crude Vegetable Oil borrowed heavily against soybean oil stored in tanks at Bayonne, New Jersey, backed by warehouse receipts from an American Express subsidiary. Most tanks held mostly seawater; oil sat only in small chambers under the sampling holes and was shuttled between tanks to be counted twice. Allied collapsed in November 1963; the brokerage firm Ira Haupt & Co. failed as a direct result, and American Express stock fell roughly 40%. Losses totaled more than $180 million; Amex later paid a $60 million settlement. De Angelis pleaded guilty to four counts and was sentenced to 20 years in 1965, paroled in 1972 — but was convicted of fraud twice more (1980, 1993) before his death in 2009. Warren Buffett bought Amex stock after the scandal, betting the franchise would survive.', '[{"title":"Salad Oil and American Express","url":"https://tontinecoffeehouse.com/2021/11/15/salad-oil-and-american-express/"},{"title":"Salad oil scandal — Wikipedia","url":"https://en.wikipedia.org/wiki/Salad_oil_scandal"}]', '[]', '2026-10-01');
INSERT INTO cards (id, headline, status, category, era, date, region, country, tags_json, wow, relevance, summary, sources_json, used_in_json, checked_on) VALUES ('CON-0003', 'A counterfeiter hand-painted $50 bills for 18 years — a wet bar counter ended it', 'Verified', 'cons-fraud', 'industrial', '1878–1896', 'americas', 'United States', '["Emanuel Ninger","Jim the Penman","counterfeiting","hand-drawn notes","Secret Service"]', 5, 3, 'German-born Emanuel Ninger, nicknamed "Jim the Penman," hand-painted counterfeit US notes from about 1878: soaking bond paper in weak coffee, tracing real notes over glass, and painting silk threads in red and blue ink. In March 1896 a $50 note got wet on the counter of a Manhattan tavern; the ink smudged and the forgery was exposed. He was sentenced in May 1896 to six years. He had confessed to about 390 notes, with estimates up to roughly 700. He died in 1924 in Pennsylvania. His exact birth year (c. 1846) is disputed and should not be stated precisely.', '[{"title":"Kings of Counterfeiting — American Numismatic Society","url":"https://numismatics.org/kings-of-counterfeiting/"},{"title":"Emanuel Ninger — Wikipedia","url":"https://en.wikipedia.org/wiki/Emanuel_Ninger"}]', '[]', '2026-10-01');
INSERT INTO cards (id, headline, status, category, era, date, region, country, tags_json, wow, relevance, summary, sources_json, used_in_json, checked_on) VALUES ('CRY-0002', 'A hacker tested Bitget''s defenses with a tiny transfer, then stole $388 million in just over an hour', 'Verified', 'crypto-fintech', 'digital', '2026-09-24', 'global-online', 'Global (Bitget exchange)', '["Bitget","exchange hack","hot wallet","zero-day","North Korea allegation"]', 5, 3, 'On 24 September 2026, an attacker who had gained high-level access through a zero-day flaw in a third-party security product sent two tiny "probe" transfers (0.184 ETH, 193 TRX) from Bitget''s wallets, small enough to stay under automated risk-alarm thresholds. Neither tripped an alert. The attacker then drained roughly $361 million across 17 transactions on 8 blockchains over about 71 minutes (6:58–8:09pm UTC); total losses reached $388 million from hot and warm wallets. Bitget''s own systems flagged a discrepancy just 7 minutes after the large transfers began — not fast enough to stop the theft. Cold wallets and customer balances were unaffected (covered by Bitget''s $464M+ User Protection Fund). Bitget suspects North Korea-linked hackers; this is the exchange''s own attribution, not confirmed by any law-enforcement body, and no individual has been named or charged.', '[{"title":"Bitget Says Attacker Exploited Third-Party Security Product Flaw to Steal $388M","url":"https://thehackernews.com/2026/09/bitget-says-attacker-exploited-third.html"},{"title":"Bitget attacker tested risk controls with small transfers before $388 million theft, CEO says","url":"https://www.theblock.co/news/regulation/2026-09-28-bitget-attacker-tested-risk-controls-small-transfers-388-million-theft-ceo-says-417045"}]', '[]', '2026-10-01');
INSERT INTO cards (id, headline, status, category, era, date, region, country, tags_json, wow, relevance, summary, sources_json, used_in_json, checked_on) VALUES ('LCK-0002', 'In 1933 the US made it illegal for citizens to own more than a handful of gold coins', 'Verified', 'money-lock', 'industrial', '1933-04-05', 'americas', 'United States', '["gold confiscation","Executive Order 6102","Roosevelt","Great Depression","hoarding","Trading with the Enemy Act"]', 5, 3, 'On 5 April 1933, President Franklin D. Roosevelt signed Executive Order 6102, requiring everyone in the continental United States to hand over gold coin, gold bullion and gold certificates to the Federal Reserve by 1 May 1933, in exchange for a fixed $20.67 per troy ounce. People could keep only up to $100 worth (about 5 ounces) plus coins of recognized collector value. Violators faced a fine of up to $10,000, up to 10 years in prison, or both. The order was issued under the WWI-era Trading with the Enemy Act (as amended by the 1933 Emergency Banking Act) — a war-powers law turned against ordinary Americans'' own savings. Less than a year later, the Gold Reserve Act of 1934 revalued gold to $35/oz, letting the government profit from gold it had just compelled citizens to sell at the lower price. The order was repealed effective 31 December 1974 (Public Law 93-373). In 2026 dollars (US CPI, ~25.6×), $20.67/oz is about $530 and the $100 exemption about $2,600 — far below today''s actual gold price, because gold itself has outpaced general inflation since 1933.', '[{"title":"Executive Order 6102 — full text (The American Presidency Project, UC Santa Barbara)","url":"https://www.presidency.ucsb.edu/documents/executive-order-6102-forbidding-the-hoarding-gold-coin-gold-bullion-and-gold-certificates"},{"title":"Federal Reserve History — Gold Reserve Act","url":"https://www.federalreservehistory.org/essays/gold-reserve-act"}]', '[]', '2026-10-01');
INSERT INTO cards (id, headline, status, category, era, date, region, country, tags_json, wow, relevance, summary, sources_json, used_in_json, checked_on) VALUES ('ODD-0001', 'On Yap, a giant stone lying at the bottom of the sea still counted as a family''s wealth', 'Verified', 'oddities-records', 'industrial', '1910', 'southeast-asia-oceania', 'Micronesia (Yap)', '["rai stones","fei","stone money","Yap","Uap","Milton Friedman","Furness"]', 5, 3, 'On the island of Yap, large carved limestone wheels called fei (rai) served as money. In his 1910 book The Island of Stone Money, American explorer and ethnographer William Henry Furness III wrote that a Yapese friend told him of a nearby family whose wealth was an enormous fei lying at the bottom of the sea. Generations earlier it had been lost in a storm while being towed home on a raft. Everyone agreed that "a few hundred feet of water off shore" did not affect its value. Big stones often changed owners without being moved. Milton Friedman retold the story in a 1991 Hoover Institution paper.', '[{"title":"William Henry Furness III, The Island of Stone Money: Uap of the Carolines (Philadelphia: Lippincott, 1910), pp. 96–98, Internet Archive (Cornell copy)","url":"https://archive.org/details/cu31924023500543"},{"title":"Milton Friedman, ''The Island of Stone Money'', Hoover Institution Working Papers in Economics E-91-3 (February 1991) — Internet Archive copy (this is the item the card previously mislabelled as Furness''s full text)","url":"https://archive.org/details/IslandOfStoneMoney"},{"title":"Milton Friedman, ''The Island of Stone Money'', Collected Works, Hoover Institution","url":"https://miltonfriedman.hoover.org/internal/media/dispatcher/215061/full"},{"title":"NPR Planet Money, The Island of Stone Money (2011)","url":"https://www.npr.org/sections/money/2011/02/15/131934618/the-island-of-stone-money"}]', '[]', '2026-10-01');
INSERT INTO cards (id, headline, status, category, era, date, region, country, tags_json, wow, relevance, summary, sources_json, used_in_json, checked_on) VALUES ('ODD-0003', 'Hungary printed a 100-quintillion-pengő note — the highest-denomination banknote ever issued', 'Verified', 'oddities-records', 'post-war', '1946', 'europe', 'Hungary', '["hyperinflation","pengő","record banknote","forint","Guinness"]', 5, 4, 'During Hungary''s 1945–46 hyperinflation — the worst on record — the government issued a 100-quintillion-pengő note (1 followed by 20 zeros), printed as "100 million b.-pengő." Guinness World Records lists it as the highest-denomination banknote ever issued (a higher, 1-sextillion-pengő note was printed but never released into circulation). The note is dated 3 June 1946 but didn''t actually enter circulation until 11 July 1946, and was withdrawn 31 July 1946 — a real circulation life of about three weeks. Something costing 1 pengő in June 1945 cost 30 septillion pengő by July 1946. In August 1946 Hungary replaced the pengő with the forint at 1 forint = 400 octillion pengő.', '[{"title":"Guinness World Records — Highest denomination banknote","url":"https://www.guinnessworldrecords.com/world-records/highest-denomination-banknote"},{"title":"Magyar Nemzeti Bank Money Museum","url":"https://penzmuzeum.hu/"}]', '[]', '2026-10-01');
INSERT INTO cards (id, headline, status, category, era, date, region, country, tags_json, wow, relevance, summary, sources_json, used_in_json, checked_on) VALUES ('ODD-0007', 'Roman soldiers were not paid in salt — the "salary" story has no ancient evidence', 'Myth', 'myths', 'ancient', 'c. 77', 'europe', 'Roman Empire', '["salary","salarium","salt","Roman army","Pliny","etymology"]', 4, 5, '"Salary" comes from Latin salarium, linked to sal, salt — but no ancient source documents Roman soldiers actually being paid in salt. Pliny the Elder (1st century AD) links salt to official posts and the word''s origin, without describing a salt-payment practice (his exact wording is still being pinned down — do not quote him directly yet). The "soldiers paid in salt" story traces to an 18th-century Latin dictionary (Facciolati–Forcellini, 1771), which guessed it by analogy with words like calcearium, "shoe money." A 1st-century-AD source (Smith''s Dictionary, 1875) describes the Augustan-era salarium as paid in money, not salt.', '[{"title":"Kiwi Hellenist: Salt and salary","url":"https://kiwihellenist.blogspot.com/2017/01/salt-and-salary.html"},{"title":"Smith''s Dictionary — Salarium","url":"https://penelope.uchicago.edu/Thayer/E/Roman/Texts/secondary/SMIGRA*/Salarium.html"}]', '[]', '2026-10-01');
INSERT INTO cards (id, headline, status, category, era, date, region, country, tags_json, wow, relevance, summary, sources_json, used_in_json, checked_on) VALUES ('REG-0002', 'In 1294 Tabriz was ordered to use Chinese-style paper money on pain of death, and the bazaar shut down until the order was withdrawn', 'Verified', 'crashes-crises', 'medieval', '1294-09-12', 'iran-middle-east', 'Iran (Ilkhanate, Tabriz)', '["čāv","chao","paper money","Gaykhatu","Ilkhanate","Tabriz","bazaar","Sadr al-Din Zanjani"]', 5, 5, 'Paper money, called čāv (from Chinese chao), was first issued in Tabriz on 19 Shawwal 693 / 12 September 1294 under the Ilkhanid ruler Gaykhatu, modelled on the paper money of Mongol-ruled (Yuan) China. The notes carried Chinese characters and the Muslim profession of faith. An edict made refusing the notes, or failing to hand in coins for exchange, punishable by death. Prices rose more than tenfold, many people left the city, and trade in the bazaars stopped. After about two months of disruption the government first allowed coins for buying food, then withdrew the paper money altogether.', '[{"title":"ČĀV — Encyclopaedia Iranica (Peter Jackson)","url":"https://www.iranicaonline.org/articles/cav-cao-from-chinese-chao-paper-money-assignat-mathews-chinese-english-dictionary-no/"},{"title":"ECONOMY v. From the Arab conquest to the end of the Il-khanids — Encyclopaedia Iranica (Ann K. S. Lambton), citing Tārīkh-e Waṣṣāf p. 274","url":"https://www.iranicaonline.org/articles/economy-5-part2/"},{"title":"Henry H. Howorth, History of the Mongols, Part III: The Mongols of Persia (1888), pp. 370–371 (after d''Ohsson and Wassaf), Internet Archive","url":"https://archive.org/details/historyofmongols03howouoft"},{"title":"Britannica, Mongol empire: The Il-Khans in Iran","url":"https://www.britannica.com/place/Mongol-empire/The-Il-Khans-in-Iran"},{"title":"Sveriges Riksbank, First banknotes in Europe (Stockholms Banco, 1661)","url":"https://www.riksbank.se/en-gb/about-the-riksbank/history/historical-timeline/1600-1699/first-banknotes-in-europe/"},{"title":"Citéco (Cité de l''Économie, Paris), The first European banknote","url":"https://www.citeco.fr/en/first-european-banknote"}]', '["SK-2026-10-05"]', '2026-10-01');
INSERT INTO cards (id, headline, status, category, era, date, region, country, tags_json, wow, relevance, summary, sources_json, used_in_json, checked_on) VALUES ('REG-0005', 'Iran''s crown jewels were once part of the reserve backing its banknotes', 'Needs-2nd-source', 'banking', 'industrial', '1930s', 'iran-middle-east', 'Iran', '["national jewels","Treasury of National Jewels","Bank Melli","Central Bank of Iran","currency reserve"]', 5, 5, 'A law passed in the 1930s transferred a major portion of Iran''s royal jewel treasury to Bank Melli Iran, where it became part of the reserve backing banknote issues. When the Central Bank of Iran was established in 1960, the treasury was transferred there, where it is still held and displayed today as the Treasury of National Jewels museum in Tehran. UNRESOLVED: sources disagree on the exact year of the transfer law (Encyclopaedia Iranica says 1935; Tehran Times and a Persian source citing Iran''s Monetary and Banking Law say 1937) — needs one more check before publishing a precise year; use "a law passed in the 1930s" as safe interim wording. Do not claim the jewels formally count as reserve today — only that they are historically custodied by the Central Bank.', '[{"title":"Crown Jewels of Persia — Encyclopaedia Iranica","url":"https://www.iranicaonline.org/articles/crown-jewels"},{"title":"Treasury of National Jewels: simply jaw-dropping! — Tehran Times","url":"https://www.tehrantimes.com/news/453928/Treasury-of-National-Jewels-simply-jaw-dropping"}]', '[]', '2026-10-01');
INSERT INTO cards (id, headline, status, category, era, date, region, country, tags_json, wow, relevance, summary, sources_json, used_in_json, checked_on) VALUES ('REG-0006', 'A Bronze Age ship sank off Kaş carrying 354 slabs of Cypriot copper, the bulk wealth of its day', 'Verified', 'origins-of-money', 'ancient', 'c. 1320 BC', 'turkiye-cyprus', 'Türkiye (Uluburun, Kaş) / Cyprus', '["Uluburun","oxhide ingot","copper","Cyprus","Kaş","Bodrum","Bronze Age trade","pre-coinage"]', 5, 5, 'In 1982 a Turkish sponge diver near Kaş reported "metal biscuits with ears" on the seabed — copper oxhide ingots from a ship that sank around 1320 BC. The Institute of Nautical Archaeology excavated it over 11 seasons (1984–1994) and more than 22,000 dives, recovering 354 copper oxhide ingots, tin ingots, and a gold scarab naming Nefertiti: over ten tons of Cypriot copper and a ton of tin. Before coinage, standardized ingots like these were how bulk metal wealth moved around the Mediterranean (the Met deliberately stops short of calling them currency). The English word "copper" derives from Latin Cyprium (aes), "metal of Cyprus" — the metal was named after the island, not the reverse. Note: keep the framing on Bronze Age trade economics, not modern Cyprus/Türkiye sovereignty.', '[{"title":"Uluburun Late Bronze Age Shipwreck Excavation — Institute of Nautical Archaeology","url":"https://nauticalarch.org/projects/uluburun-late-bronze-age-shipwreck-excavation/"},{"title":"Copper ingot, Cypriot, Late Bronze Age — The Metropolitan Museum of Art","url":"https://www.metmuseum.org/art/collection/search/248493"}]', '[]', '2026-10-01');
INSERT INTO cards (id, headline, status, category, era, date, region, country, tags_json, wow, relevance, summary, sources_json, used_in_json, checked_on) VALUES ('WIR-0002', 'A trading-bot company allegedly forged its own SEC certificate to convince investors it was real — the bots never existed', 'Verified', 'cons-fraud', 'digital', '2026-09-29', 'global-online', 'unclear (likely overseas per SEC)', '["SEC","TSAI","AI trading bot","fake SEC certificate","Form D","crypto fraud","recruitment commission"]', 5, 3, 'On 29 September 2026 the SEC filed a civil fraud complaint (SDNY) against TSAI Pro Ltd. and TSAI Capital Foundation, alleging they invited investors to "rent" AI trading bots for fees of $100 to $500,000, promoted via a website, WhatsApp and Facebook with a recruitment-commission structure. The SEC alleges TSAI posted a falsified SEC regulatory certificate and a fabricated Form D filing to look officially registered — no bots and no real trading ever existed. About $2.8 million was raised from roughly 1,715 investors between September 2024 and March 2025. This is a civil complaint, not a criminal charge: nothing has been proven in court and no individual has been named or convicted.', '[{"title":"SEC Charges Multiple Entities in Fraud Schemes Totaling at Least $15 Million That Used WhatsApp, Other Platforms","url":"https://www.sec.gov/newsroom/press-releases/2026-95-sec-charges-multiple-entities-fraud-schemes-totaling-least-15-million-used-whatsapp-other-platforms"},{"title":"SEC Litigation Release LR-26654","url":"https://www.sec.gov/enforcement-litigation/litigation-releases/lr-26654"}]', '["SK-2026-10-08"]', '2026-10-01');
